#include <bits/stdc++.h>
using namespace std;
struct Opt{int id,p,x,c;};vector<Opt>v;vector<int>S,A,B;int target,px=0,xx=0;long long supports=0,parity=0,partitions=0,relations=0,primitive_count=0;int stamp[2048]={},epoch=0;bool hit=false;vector<int>wA,wB;bool found=false;
void subset(const vector<int>&L,int at,int left,int p,int x,bool put){if(hit)return;if(!left){int q=(p<<7)|(x&127);if(put)stamp[q]=epoch;else if(stamp[q]==epoch)hit=true;return;}for(int i=at;i<=(int)L.size()-left;i++)subset(L,i+1,left-1,p^v[L[i]].p,x+v[L[i]].x,put);}
bool prim(){for(int j=2;j<=4;j++){++epoch;hit=false;subset(A,0,j,0,0,true);subset(B,0,j,0,0,false);if(hit)return false;}return true;}
void partition(int at,int left,int sum,int mask){if(!left){partitions++;if((2*sum-xx)&127)return;relations++;A.clear();B.clear();for(int i=0;i<18;i++)((mask>>i&1)?A:B).push_back(S[i]);if(prim()){primitive_count++;if(!found){wA=A;wB=B;found=true;}}return;}for(int i=at;i<=18-left;i++)partition(i+1,left-1,sum+v[S[i]].x,mask|(1<<i));}
void support(int at,int left,int cost,int p,int x){if(cost+2*left>target)return;if(!left){if(cost!=target)return;supports++;if(p||(x&1))return;parity++;xx=x;partition(1,8,v[S[0]].x,1);return;}for(int i=at;i<=(int)v.size()-left;i++){S.push_back(i);support(i+1,left-1,cost+v[i].c,p^v[i].p,x+v[i].x);S.pop_back();}}
int main(int argc,char**argv){target=argc>1?atoi(argv[1]):37;Opt z;while(cin>>z.id>>z.p>>z.x>>z.c)v.push_back(z);support(0,18,0,0,0);cout<<"{\"cost\":"<<target<<",\"support_sets\":"<<supports<<",\"parity_admissible_support_sets\":"<<parity<<",\"balanced_partitions_examined\":"<<partitions<<",\"equal_charge_relations\":"<<relations<<",\"primitive_relations\":"<<primitive_count;if(found){cout<<",\"first_plus\":[";for(int i=0;i<9;i++){if(i)cout<<",";cout<<v[wA[i]].id;}cout<<"],\"first_minus\":[";for(int i=0;i<9;i++){if(i)cout<<",";cout<<v[wB[i]].id;}cout<<"]";}cout<<"}"<<endl;}
